/**
 * Enforces org-wide log retention in system context.
 * Deletes a bounded set directly and uses Batch Apex for any backlog.
 */
public without sharing class LogPurgeJob
    implements Schedulable, Database.Batchable<SObject> {

    private Datetime retentionReference;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        retentionReference = System.now();

        Integer rowLimit = Math.min(
            Limits.getLimitDmlRows() - Limits.getDmlRows(),
            Limits.getLimitQueryRows() - Limits.getQueryRows()
        );

        if (rowLimit <= 0) {
            Database.executeBatch(this, 200);
            return;
        }

        Datetime standardCutoff = retentionReference.addDays(-30);
        Datetime errorCutoff = retentionReference.addDays(-180);

        List<FB_Integration_Log__c> expiredLogs = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorCutoff
               OR (
                   CreatedDate < :standardCutoff
                   AND (Level__c = null OR Level__c != 'ERROR')
               )
            LIMIT :rowLimit
        ];

        if (!expiredLogs.isEmpty()) {
            delete expiredLogs;
        }

        // A full result set may mean more records remain. The batch queries
        // after this transaction commits, excluding the records just deleted.
        if (expiredLogs.size() == rowLimit) {
            Database.executeBatch(this, 200);
        }
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        if (retentionReference == null) {
            retentionReference = System.now();
        }

        Datetime standardCutoff = retentionReference.addDays(-30);
        Datetime errorCutoff = retentionReference.addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE CreatedDate < :errorCutoff
               OR (
                   CreatedDate < :standardCutoff
                   AND (Level__c = null OR Level__c != 'ERROR')
               )
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<SObject> scope
    ) {
        // Surface deletion failures instead of silently skipping records.
        delete scope;
    }

    public void finish(Database.BatchableContext context) {
        // No post-processing required.
    }

    /**
     * Runs daily at 02:00 in the scheduling user's time zone.
     */
    public static Id scheduleNightly() {
        return (Id) System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
