@IsTest
private class OpportunitiesServiceTest {
    /*
     * DomainFactory's mock registry is keyed by SObjectType, not by the
     * records supplied to newInstance. These tests verify selection, domain
     * invocation, forwarded arguments, and execution order. Verifying the
     * exact list passed into the static domain factory would require an
     * injectable factory seam in production code; stubbing getRecords()
     * on the domain would not verify that argument.
     */

    // Match null as well, so extra calls with null arguments cannot escape
    // the total-invocation-count assertions.
    private class AnyArgument implements fflib_IMatcher {
        public Boolean matches(Object argument) {
            return true;
        }
    }

    private static Decimal anyPercentage() {
        return (Decimal) fflib_Match.matches(new AnyArgument());
    }

    private static fflib_ISObjectUnitOfWork anyUnitOfWork() {
        return (fflib_ISObjectUnitOfWork)
            fflib_Match.matches(new AnyArgument());
    }

    private static Set<Id> anyIds() {
        return (Set<Id>) fflib_Match.matches(new AnyArgument());
    }

    private class RecordInvocation implements fflib_Answer {
        private List<String> events;
        private String eventName;

        RecordInvocation(List<String> events, String eventName) {
            this.events = events;
            this.eventName = eventName;
        }

        public Object answer(fflib_InvocationOnMock invocation) {
            events.add(eventName);
            return null;
        }
    }

    private class Fixture {
        fflib_ApexMocks mocks;
        IOpportunitiesSelector selector;
        IOpportunities domain;
        fflib_ISObjectUnitOfWork uow;

        Set<Id> ids;
        List<Opportunity> selected;
        List<String> events;

        Integer initialQueries;
        Integer initialDmlStatements;

        Fixture() {
            initialQueries = Limits.getQueries();
            initialDmlStatements = Limits.getDmlStatements();

            mocks = new fflib_ApexMocks();
            selector = (IOpportunitiesSelector)
                mocks.mock(IOpportunitiesSelector.class);
            domain = (IOpportunities) mocks.mock(IOpportunities.class);
            uow = (fflib_ISObjectUnitOfWork)
                mocks.mock(fflib_ISObjectUnitOfWork.class);

            Id firstId = fflib_IDGenerator.generate(Opportunity.SObjectType);
            Id secondId = fflib_IDGenerator.generate(Opportunity.SObjectType);

            ids = new Set<Id>{ firstId, secondId };
            selected = new List<Opportunity>{
                new Opportunity(
                    Id = firstId,
                    Name = 'First opportunity',
                    Amount = 123.45
                ),
                new Opportunity(
                    Id = secondId,
                    Name = 'Second opportunity',
                    Amount = 987.65
                )
            };
            events = new List<String>();

            mocks.startStubbing();

            // Factory registration calls these methods to determine the key.
            mocks.when(selector.sObjectType())
                .thenReturn(Opportunity.SObjectType);
            mocks.when(domain.sObjectType())
                .thenReturn(Opportunity.SObjectType);
            mocks.when(selector.selectById(ids)).thenReturn(selected);

            ((IOpportunities) mocks.doAnswer(
                new RecordInvocation(events, 'applyDiscount'),
                domain
            )).applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.doAnswer(
                new RecordInvocation(events, 'commitWork'),
                uow
            )).commitWork();

            mocks.stopStubbing();

            // Explicit casts disambiguate the DomainFactory overloads.
            Application.Domain.setMock((fflib_ISObjectDomain) domain);
            Application.Selector.setMock((fflib_ISObjectSelector) selector);
            Application.UnitOfWork.setMock(uow);
        }

        void assertNoDatabaseWork() {
            System.assertEquals(
                initialQueries,
                Limits.getQueries(),
                'No SOQL may be executed.'
            );
            System.assertEquals(
                initialDmlStatements,
                Limits.getDmlStatements(),
                'No DML may be executed.'
            );
        }

        void assertNothingAppliedOrCommitted() {
            ((IOpportunitiesSelector) mocks.verify(selector, 0))
                .selectById(anyIds());

            ((IOpportunities) mocks.verify(domain, 0))
                .applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0))
                .commitWork();

            System.assertEquals(
                0,
                events.size(),
                'Neither applyDiscount nor commitWork may run.'
            );
            assertNoDatabaseWork();
        }

        void assertAppliedAndCommitted(Decimal percentage) {
            // Verify the exact request and exclude additional selections.
            ((IOpportunitiesSelector) mocks.verify(selector, 1))
                .selectById(ids);
            ((IOpportunitiesSelector) mocks.verify(selector, 1))
                .selectById(anyIds());

            // Verify the unchanged percentage and the injected UoW.
            ((IOpportunities) mocks.verify(domain, 1))
                .applyDiscount(percentage, uow);

            // Exclude additional calls, including different/null arguments.
            ((IOpportunities) mocks.verify(domain, 1))
                .applyDiscount(anyPercentage(), anyUnitOfWork());

            ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1))
                .commitWork();

            // This records actual execution order, not verification order.
            System.assertEquals(
                new List<String>{ 'applyDiscount', 'commitWork' },
                events,
                'Apply exactly once, then commit exactly once.'
            );

            System.assertEquals(
                Decimal.valueOf('123.45'),
                selected[0].Amount,
                'The real domain must not run.'
            );
            System.assertEquals(
                Decimal.valueOf('987.65'),
                selected[1].Amount,
                'The real domain must not run.'
            );

            assertNoDatabaseWork();
        }
    }

    @IsTest
    static void invalidPercentagesThrowBeforeProcessingAnyIds() {
        List<Decimal> invalidPercentages = new List<Decimal>{
            null, -1, 0, 50.01, 100
        };

        for (Decimal percentage : invalidPercentages) {
            // Validation must precede the null/empty-ID short circuit.
            for (Integer idCase = 0; idCase < 3; idCase++) {
                Fixture fixture = new Fixture();
                Set<Id> requestedIds;

                if (idCase == 0) {
                    requestedIds = null;
                } else if (idCase == 1) {
                    requestedIds = new Set<Id>();
                } else {
                    requestedIds = fixture.ids;
                }

                Boolean threwExpectedException = false;
                try {
                    OpportunitiesService.applyDiscounts(
                        requestedIds,
                        percentage
                    );
                } catch (
                    OpportunitiesService.OpportunitiesServiceException expected
                ) {
                    threwExpectedException = true;
                }

                System.assert(
                    threwExpectedException,
                    'Expected OpportunitiesServiceException for percentage ' +
                    String.valueOf(percentage) + ', ID case ' + idCase
                );
                fixture.assertNothingAppliedOrCommitted();
            }
        }
    }

    @IsTest
    static void nullIdsDoNothingForValidPercentages() {
        for (Decimal percentage : new List<Decimal>{ 0.01, 12.5, 50 }) {
            Fixture fixture = new Fixture();

            OpportunitiesService.applyDiscounts(null, percentage);

            fixture.assertNothingAppliedOrCommitted();
        }
    }

    @IsTest
    static void emptyIdsDoNothingForValidPercentages() {
        for (Decimal percentage : new List<Decimal>{ 0.01, 12.5, 50 }) {
            Fixture fixture = new Fixture();

            OpportunitiesService.applyDiscounts(new Set<Id>(), percentage);

            fixture.assertNothingAppliedOrCommitted();
        }
    }

    @IsTest
    static void validPercentagesAreForwardedOnceBeforeCommit() {
        // Cover a small positive value, fractional values, and the upper bound.
        for (Decimal percentage : new List<Decimal>{ 0.01, 1, 12.5, 49.99, 50 }) {
            Fixture fixture = new Fixture();

            OpportunitiesService.applyDiscounts(fixture.ids, percentage);

            fixture.assertAppliedAndCommitted(percentage);
        }
    }

    @IsTest
    static void nonemptyIdsStillApplyAndCommitWhenSelectionIsEmpty() {
        Fixture fixture = new Fixture();

        fixture.mocks.startStubbing();
        fixture.mocks.when(fixture.selector.selectById(fixture.ids))
            .thenReturn(new List<Opportunity>());
        fixture.mocks.stopStubbing();

        OpportunitiesService.applyDiscounts(fixture.ids, 25);

        // The early return depends on input IDs, not the selector's result.
        fixture.assertAppliedAndCommitted(25);
    }
}
