@IsTest
private class OpportunityForecastServiceTest {
    @IsTest
    static void sumsWeightedAmountsByStageAndRoundsEachOpportunity() {
        Id accountA = fflib_IDGenerator.generate(Account.SObjectType);
        Id accountB = fflib_IDGenerator.generate(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountA, accountB };

        List<Opportunity> opportunities = new List<Opportunity>{
            // Each weight is 3.3033, rounded to 3.30 before summing.
            // Rounding only the final total would incorrectly yield 6.61.
            opportunity(accountA, 'Prospecting', 10.01, 33),
            opportunity(accountB, 'Prospecting', 10.01, 33),

            // Exercise upward rounding, another stage and another probability.
            opportunity(accountA, 'Qualification', 10.02, 33),
            opportunity(accountB, 'Qualification', 200, 75),

            // Missing inputs must not affect existing totals.
            opportunity(accountA, 'Prospecting', null, 50),
            opportunity(accountB, 'Qualification', 100, null),

            // Missing inputs must not create otherwise absent stage entries.
            opportunity(accountA, 'Needs Analysis', null, 50),
            opportunity(accountB, 'Value Proposition', 100, null),
            opportunity(accountA, 'Perception Analysis', null, null),

            // Zero inputs are valid and must create zero-valued entries.
            opportunity(accountA, 'Proposal/Price Quote', 0, 80),
            opportunity(accountB, 'Negotiation/Review', 100, 0)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selector = registerSelector(mocks, opportunities);

        Test.startTest();
        Map<String, Decimal> actual =
            OpportunityForecastService.weightedAmountByStage(accountIds);
        assertNoDatabaseWork();
        Test.stopTest();

        Map<String, Decimal> expected = new Map<String, Decimal>{
            'Prospecting' => 6.60,
            'Qualification' => 153.31,
            'Proposal/Price Quote' => 0.00,
            'Negotiation/Review' => 0.00
        };

        System.assertEquals(
            expected,
            actual,
            'Sum individually rounded weights by stage, ignoring missing inputs.'
        );
        verifyOneSelection(mocks, selector, accountIds);
    }

    @IsTest
    static void noReturnedOpportunitiesProducesEmptyMap() {
        Set<Id> accountIds = new Set<Id>{
            fflib_IDGenerator.generate(Account.SObjectType)
        };
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selector =
            registerSelector(mocks, new List<Opportunity>());

        Test.startTest();
        Map<String, Decimal> actual =
            OpportunityForecastService.weightedAmountByStage(accountIds);
        assertNoDatabaseWork();
        Test.stopTest();

        System.assertEquals(
            new Map<String, Decimal>(),
            actual,
            'An empty selector result must produce an empty, non-null map.'
        );
        verifyOneSelection(mocks, selector, accountIds);
    }

    @IsTest
    static void nullAccountIdsReturnEmptyMapWithoutSelection() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selector =
            registerSelector(mocks, new List<Opportunity>());

        Test.startTest();
        Map<String, Decimal> actual =
            OpportunityForecastService.weightedAmountByStage(null);
        assertNoDatabaseWork();
        Test.stopTest();

        System.assertEquals(
            new Map<String, Decimal>(),
            actual,
            'Null account ids must produce an empty, non-null map.'
        );
        verifyNoSelection(mocks, selector);
    }

    @IsTest
    static void emptyAccountIdsReturnEmptyMapWithoutSelection() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunitiesSelector selector =
            registerSelector(mocks, new List<Opportunity>());

        Test.startTest();
        Map<String, Decimal> actual =
            OpportunityForecastService.weightedAmountByStage(new Set<Id>());
        assertNoDatabaseWork();
        Test.stopTest();

        System.assertEquals(
            new Map<String, Decimal>(),
            actual,
            'Empty account ids must produce an empty, non-null map.'
        );
        verifyNoSelection(mocks, selector);
    }

    private static IOpportunitiesSelector registerSelector(
        fflib_ApexMocks mocks,
        List<Opportunity> opportunities
    ) {
        IOpportunitiesSelector selector =
            (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        mocks.startStubbing();
        // fflib_ISObjectSelector exposes sObjectType(), which the factory
        // calls when registering a selector mock.
        mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(
            selector.selectOpenByAccountIds(
                (Set<Id>) fflib_Match.anyObject()
            )
        ).thenReturn(opportunities);
        mocks.stopStubbing();

        Application.Selector.setMock(selector);
        return selector;
    }

    private static void verifyOneSelection(
        fflib_ApexMocks mocks,
        IOpportunitiesSelector selector,
        Set<Id> expectedAccountIds
    ) {
        // Verify the actual account ids, not merely that a call occurred.
        ((IOpportunitiesSelector) mocks.verify(selector, 1))
            .selectOpenByAccountIds(expectedAccountIds);

        // Reject additional calls with other sets.
        ((IOpportunitiesSelector) mocks.verify(selector, 1))
            .selectOpenByAccountIds((Set<Id>) fflib_Match.anyObject());

        ((IOpportunitiesSelector) mocks.verify(selector, 0))
            .selectOpenByAccountIds(null);
    }

    private static void verifyNoSelection(
        fflib_ApexMocks mocks,
        IOpportunitiesSelector selector
    ) {
        ((IOpportunitiesSelector) mocks.verify(selector, 0))
            .selectOpenByAccountIds((Set<Id>) fflib_Match.anyObject());

        // Explicitly check null independently of wildcard null semantics.
        ((IOpportunitiesSelector) mocks.verify(selector, 0))
            .selectOpenByAccountIds(null);
    }

    private static void assertNoDatabaseWork() {
        System.assertEquals(
            0,
            Limits.getQueries(),
            'The service must not execute SOQL when using the selector mock.'
        );
        System.assertEquals(
            0,
            Limits.getDmlStatements(),
            'Forecast calculation must not execute DML.'
        );
    }

    private static Opportunity opportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            AccountId = accountId,
            Name = 'In-memory forecast opportunity',
            StageName = stageName,
            CloseDate = Date.newInstance(2030, 1, 31),
            Amount = amount,
            Probability = probability
        );
    }
}
