public with sharing class GiftImportService {
    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        List<npsp__DataImport__c> stagedRows =
            new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            ImportResult result = new ImportResult();
            result.success = false;
            results.add(result);

            npsp__DataImport__c row = new npsp__DataImport__c(
                npsp__Donation_Donor__c = 'Contact1'
            );

            // Let NPSP validate the gift and apply its donor-matching rules.
            // A null gift becomes an incomplete staging row.
            if (gift != null) {
                row.npsp__Contact1_Firstname__c = gift.firstName;
                row.npsp__Contact1_Lastname__c = gift.lastName;
                row.npsp__Contact1_Personal_Email__c = gift.email;
                row.npsp__Donation_Amount__c = gift.amount;
                row.npsp__Donation_Date__c = gift.giftDate;
            }

            stagedRows.add(row);
        }

        // Enforce the caller's staging permissions while allowing individual
        // staging failures without blocking the remaining rows.
        Database.SaveResult[] saveResults = Database.insert(
            stagedRows,
            false,
            AccessLevel.USER_MODE
        );

        List<npsp__DataImport__c> rowsToProcess =
            new List<npsp__DataImport__c>();
        Map<Id, Integer> inputIndexByImportId = new Map<Id, Integer>();

        for (Integer i = 0; i < saveResults.size(); i++) {
            Database.SaveResult saved = saveResults[i];

            if (saved.isSuccess()) {
                stagedRows[i].Id = saved.getId();
                rowsToProcess.add(stagedRows[i]);
                inputIndexByImportId.put(saved.getId(), i);
            } else {
                // No NPSP failure information exists if staging itself fails.
                results[i].errorMessage = formatStagingErrors(
                    saved.getErrors()
                );
            }
        }

        if (rowsToProcess.isEmpty()) {
            return results;
        }

        // Run synchronously using the org's existing import configuration.
        // The third argument disables deletion of imported staging records,
        // preserving them as the audit trail.
        npsp.BDI_DataImport_API.processDataImportBatch(
            rowsToProcess,
            npsp__Data_Import_Settings__c.getOrgDefaults(),
            false
        );

        Set<Id> importIds = inputIndexByImportId.keySet();

        // Read persisted results; do not assume the API updates our in-memory
        // instances. NPSP records individual processing failures on these rows.
        Map<Id, npsp__DataImport__c> processedById =
            new Map<Id, npsp__DataImport__c>([
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                FROM npsp__DataImport__c
                WHERE Id IN :importIds
                WITH USER_MODE
            ]);

        for (Id importId : importIds) {
            ImportResult result =
                results[inputIndexByImportId.get(importId)];
            npsp__DataImport__c processed = processedById.get(importId);

            if (processed == null) {
                result.errorMessage =
                    'The staged Data Import record could not be read after processing.';
                continue;
            }

            result.success = processed.npsp__Status__c == 'Imported';
            result.contactId = processed.npsp__Contact1Imported__c;
            result.opportunityId = processed.npsp__DonationImported__c;
            result.errorMessage = result.success
                ? null
                : processed.npsp__FailureInformation__c;
        }

        // Transaction-level exceptions deliberately propagate rather than
        // being misrepresented as NPSP row-level failures.
        return results;
    }

    private static String formatStagingErrors(Database.Error[] errors) {
        List<String> messages = new List<String>();

        for (Database.Error error : errors) {
            messages.add(
                String.valueOf(error.getStatusCode()) +
                ': ' +
                error.getMessage()
            );
        }

        return 'Unable to stage Data Import record: ' +
            String.join(messages, '; ');
    }
}
