public inherited sharing class TA_Opportunity_CollectForErpSync
    implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> opportunityIds = new Set<Id>();

        for (SObject record : triggerNew) {
            opportunityIds.add(record.Id);
        }

        OpportunityErpSyncFinalizer.collect(opportunityIds);
    }

    public void afterUpdate(
        List<SObject> triggerNew,
        List<SObject> triggerOld
    ) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        Set<Id> opportunityIds = new Set<Id>();

        for (SObject record : triggerNew) {
            Opportunity currentOpportunity = (Opportunity) record;
            Opportunity previousOpportunity =
                (Opportunity) oldById.get(currentOpportunity.Id);

            if (currentOpportunity.StageName != previousOpportunity.StageName) {
                opportunityIds.add(currentOpportunity.Id);
            }
        }

        OpportunityErpSyncFinalizer.collect(opportunityIds);
    }
}
